public class ResourcePrefixDetector extends Detector implements XmlScanner, ResourceFolderScanner {
    private static final String ATTR_NAME = "name";
    private static final Implementation IMPLEMENTATION = new Implementation(
            ResourcePrefixDetector.class,
            Scope.RESOURCE_FILE_SCOPE);
    public static final Issue ISSUE = Issue.create(
            "ResourceName",
            "Resource with Wrong Prefix",
            "...",
            Category.CORRECTNESS, 5, Severity.WARNING, IMPLEMENTATION);

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(VALUE_RESOURCE_TAGS);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String prefix = getResourcePrefix(context);
        if (prefix == null || prefix.isEmpty()) {
            return;
        }
        Attr attribute = element.getAttributeNode(ATTR_NAME);
        if (attribute == null) return;
        String name = attribute.getValue();
        if (name == null || name.isEmpty() || name.indexOf(':') != -1) return;
        if (!name.startsWith(prefix)) {
            context.report(ISSUE, attribute, context.getValueLocation(attribute),
                String.format("Resource named `%1$s` does not start with ...", name, prefix));
        }
    }

    @Override
    public void checkFolder(@NonNull ResourceContext context, @NonNull String folderName) {
        String prefix = getResourcePrefix(context);
        if (prefix == null || prefix.isEmpty()) return;
        ResourceFolderType folderType = context.getFolderType();
        if (folderType == ResourceFolderType.VALUES) return;
        File folder = context.getFolder();
        File[] files = folder.listFiles();
        if (files == null) return;
        for (File file : files) {
            if (file.isDirectory()) continue;
            String fileName = file.getName();
            if (fileName.startsWith(".")) continue;
            String name = getResourceName(file);
            if (name.isEmpty()) continue;
            if (!name.startsWith(prefix)) {
                context.report(ISSUE, Location.create(file), String.format(...));
            }
        }
    }

    @Nullable
    private static String getResourcePrefix(@NonNull Context context) {
        return context.getProject().getResourcePrefix();
    }
}
```

